#include <iostream>

int main() {
    // Definite iteration: exactly 3 fixed items
    std::cout << "Definite:";
    unsigned int count = 1;
    while (count <= 3) {
        std::cout << " " << count;
        ++count;
    }
    std::cout << "\n";

    // Indefinite iteration: read numbers until sentinel (-1) is encountered
    std::cout << "Indefinite:";
    int val = 0;
    while (std::cin >> val && val != -1) {
        std::cout << " " << val;
    }
    std::cout << "\n";

    return 0;
}

#include <iostream>

int main() {
    // Implementation using while
    unsigned int counter = 1;
    std::cout << "while:";
    while (counter <= 5) {
        std::cout << " " << counter;
        ++counter;
    }
    std::cout << "\n";

    // Equivalent modern C++ for statement
    std::cout << "for:";
    for (unsigned int i = 1; i <= 5; ++i) {
        std::cout << " " << i;
    }
    std::cout << "\n";

    return 0;
}
